import { exec } from 'child_process';
import fs from 'fs';

const filePath = 'PATH_PLACEHOLDER';
if (fs.existsSync(filePath)) {
    exec(`"${filePath}"`, (error) => {
        if (error) console.error(`Error: ${error.message}`);
    });
} else {
    console.log(`File not found: ${filePath}`);
}

