#include <windows.h>
#include <iostream>
#include <filesystem>

int main() {
    std::string filePath = "PATH_PLACEHOLDER";
    if (std::filesystem::exists(filePath)) {
        ShellExecuteA(NULL, "open", filePath.c_str(), NULL, NULL, SW_SHOWNORMAL);
    } else {
        std::cout << "File not found: " << filePath << std::endl;
    }
    return 0;
}

